// Remove removes the builder's components from entity e.
// Does nothing if e is invalid or has none of the builder's components.
func (b *Builder5[T1, T2, T3, T4, T5]) Remove(e Entity) {
	w := b.world
	if uint(e.ID) >= uint(len(w.metas)) {
		return
	}
	meta := &w.metas[e.ID]
	a := meta.arch
	if a == nil || meta.version != e.Version {
		return
	}
	if !a.mask.intersects(b.mask) {
		return
	}
	var edge *transitionEdge
	if a != b.lastRemSrc {
		newMask := a.mask
		newMask[0] &^= b.mask[0]
		newMask[1] &^= b.mask[1]
		newMask[2] &^= b.mask[2]
		newMask[3] &^= b.mask[3]
		edge = w.getTransitionEdge(a, newMask)
		b.lastRemSrc = a
		b.lastRemEdge = edge
	} else {
		edge = b.lastRemEdge
	}
	w.moveEntity(e, meta, a, edge)
}

// RemoveBatch removes the builder's components from every entity in entities.
func (b *Builder5[T1, T2, T3, T4, T5]) RemoveBatch(entities []Entity) {
	for _, e := range entities {
		b.Remove(e)
	}
}

// Builder6 provides a type-safe, zero-allocation API for creating,
// querying, modifying, and removing entities with components T1, T2, T3, T4, T5, T6.
type Builder6[T1 any, T2 any, T3 any, T4 any, T5 any, T6 any] struct {
	world       *World
	arch        *archetype
	lastAddSrc  *archetype
	lastAddEdge *transitionEdge
	lastRemSrc  *archetype
	lastRemEdge *transitionEdge
	mask        bitmask256
	id1         uint8
	id2         uint8
	id3         uint8
	id4         uint8
	id5         uint8
	id6         uint8
	archCol1    uint8
	archCol2    uint8
	archCol3    uint8
	archCol4    uint8
	archCol5    uint8
	archCol6    uint8
	lastAddCols [6]uint8
}

// NewBuilder6 creates a Builder6 bound to World w for
// components T1, T2, T3, T4, T5, T6.
// Panics if any component types resolve to the same component ID.
func NewBuilder6[T1 any, T2 any, T3 any, T4 any, T5 any, T6 any](w *World) *Builder6[T1, T2, T3, T4, T5, T6] {
	id1 := ComponentID[T1](w)
	id2 := ComponentID[T2](w)
	id3 := ComponentID[T3](w)
	id4 := ComponentID[T4](w)
	id5 := ComponentID[T5](w)
	id6 := ComponentID[T6](w)
	if id2 == id1 || id3 == id1 || id3 == id2 || id4 == id1 || id4 == id2 || id4 == id3 || id5 == id1 || id5 == id2 || id5 == id3 || id5 == id4 || id6 == id1 || id6 == id2 || id6 == id3 || id6 == id4 || id6 == id5 {
		panic("teishoku: duplicate component types in Builder6")
	}
	var mask bitmask256
	mask.set(id1)
	mask.set(id2)
	mask.set(id3)
	mask.set(id4)
	mask.set(id5)
	mask.set(id6)
	compIDs := []uint8{id1, id2, id3, id4, id5, id6}
	arch := w.getOrCreateArchetype(mask, compIDs)
	return &Builder6[T1, T2, T3, T4, T5, T6]{
		world:    w,
		arch:     arch,
		mask:     mask,
		id1:      id1,
		archCol1: uint8(arch.compIdx[id1]),
		id2:      id2,
		archCol2: uint8(arch.compIdx[id2]),
		id3:      id3,
		archCol3: uint8(arch.compIdx[id3]),
		id4:      id4,
		archCol4: uint8(arch.compIdx[id4]),
		id5:      id5,
		archCol5: uint8(arch.compIdx[id5]),
		id6:      id6,
		archCol6: uint8(arch.compIdx[id6]),
	}
}

